import{_ as r,C as o,o as a,c as n,ag as t,E as l}from"./chunks/framework.CtWPcAmt.js";const _=JSON.parse('{"title":"Customer Management","description":"","frontmatter":{},"headers":[],"relativePath":"customers/customer-management.md","filePath":"customers/customer-management.md","lastUpdated":1786088921000}'),m={name:"customers/customer-management.md"};function c(i,e,u,d,h,g){const s=o("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="customer-management" tabindex="-1">Customer Management <a class="header-anchor" href="#customer-management" aria-label="Permalink to &quot;Customer Management&quot;">​</a></h1><p>A seller can see the customers who have bought from them under <strong>Customers</strong> in the Seller Panel — a focused view of their own buyers, with spend and order metrics, without exposing the marketplace&#39;s full customer base.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Which customers a seller can see</li><li>What the customers view tracks</li></ul></div><h2 id="your-customers" tabindex="-1">Your customers <a class="header-anchor" href="#your-customers" aria-label="Permalink to &quot;Your customers&quot;">​</a></h2><p>Open <strong>Customers</strong> in the Seller Panel. The list shows the customers who have placed orders for this seller&#39;s products, with columns for the <strong>customer</strong>, <strong>email</strong>, <strong>gender</strong>, <strong>revenue</strong>, <strong>order count</strong>, <strong>status</strong>, and <strong>customer group</strong>.</p>',5)),l(s,{src:"/images/customer-management/customers.png",alt:"Seller customers view"}),e[1]||(e[1]=t('<ul><li><strong>Revenue</strong> is what that customer has spent with this seller — the invoiced total of their orders, excluding cancelled and closed ones.</li><li><strong>Order Count</strong> is how many orders they&#39;ve placed with the seller.</li><li>The list is searchable and filterable by group and status.</li></ul><div class="info custom-block"><p class="custom-block-title">Sellers see only their own buyers</p><p>A seller only sees customers who have bought from <em>them</em> — not every customer on the marketplace, and not guest buyers who never created an account. Whether a seller can see customer email addresses is itself governed by an admin permission; when it&#39;s off, emails are masked. Full customer management across the platform stays with the admin.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use this view to recognise repeat buyers and understand your audience. For sales and buyer <strong>trends over time</strong>, see <a href="/reporting/seller-reporting">Seller Reporting</a>.</p></div>',3))])}const f=r(m,[["render",c]]);export{_ as __pageData,f as default};
